examples.template:
MonarchSectionCard(
    title = {{heading}},
    description = {{description}},
    tone = MonarchTone.Danger,
) {
    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
        Row(
            modifier = Modifier.semantics { isTraversalGroup = true },
            horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
            verticalAlignment = Alignment.CenterVertically,
        ) {
          Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
            MonarchText(text = {{items.0.title}}, style = MonarchTextStyle.BodyStrong, heading = true)
            MonarchText(
                text = {{items.0.description}},
                style = MonarchTextStyle.Caption,
                color = MonarchTheme.colors.textMuted,
            )
          }
            MonarchButton(
                text = {{items.0.action.label}},
                onClick = {},
                variant = MonarchButtonVariant.{{items.0.action.variant|pascal}},
            )
        }
        MonarchDivider(variant = MonarchDividerVariant.Subtle)
        Row(
            modifier = Modifier.semantics { isTraversalGroup = true },
            horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
            verticalAlignment = Alignment.CenterVertically,
        ) {
          Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
            MonarchText(text = {{items.1.title}}, style = MonarchTextStyle.BodyStrong, heading = true)
            MonarchText(
                text = {{items.1.description}},
                style = MonarchTextStyle.Caption,
                color = MonarchTheme.colors.textMuted,
            )
          }
            MonarchButton(
                text = {{items.1.action.label}},
                onClick = { confirming = true },
                variant = MonarchButtonVariant.{{items.1.action.variant|pascal}},
                enabled = !deleted,
            )
        }
    }
}
if (confirming) {
    MonarchDialog(
        onDismissRequest = { confirming = false },
        title = "Delete this workspace?",
        description = "Every project, file and member is deleted. This cannot be undone.",
        actions = {
            MonarchButton(text = "Cancel", onClick = { confirming = false }, variant = MonarchButtonVariant.Secondary)
            MonarchButton(
                text = "Delete",
                onClick = {
                    deleted = true
                    confirming = false
                },
                variant = MonarchButtonVariant.Danger,
            )
        },
    )
}

